#include "apps.h"
#include "app_stage_e.h"
#include "heap.h"
#include "fat32.h"
#include "keyboard.h"
#define FACET_PATH "/disk/Sanctum/system/ui-config.ini"
typedef struct{int selected;bool dark;char status[48];}facet_t;
static const uint32_t ca[6]={0xFFF0A33A,0xFFC9B6DC,0xFFE9A03B,0xFF9EBBE0,0xFF91C5B0,0xFFF2C889};
static const uint32_t cb[6]={0xFFCC5A82,0xFFB796C8,0xFFD56D8A,0xFF7A9DCE,0xFF69AA91,0xFFDB9E72};
static const char*names[6]={"Ring motion","Lilac drift","Ignition","Mesh study","Cold strata","Warm light"};
static void facet_apply(facet_t*s){ui_theme_set_dark(s->dark);ui_theme_set_accent(ca[s->selected],ui_lerp(ca[s->selected],cb[s->selected],128),cb[s->selected]);if(!fat32_is_mounted()){se_copy(s->status,"Not saved - RAM only",48);return;}fat32_mkdir_p("/disk/Sanctum/system");char b[64];int n=0;const char*p="theme=";while(*p)b[n++]=*p++;b[n++]=(char)('0'+s->selected);b[n++]='\n';p="dark=";while(*p)b[n++]=*p++;b[n++]=s->dark?'1':'0';b[n++]='\n';fat32_save_file(FACET_PATH,b,n);se_copy(s->status,"active facet persisted",48);}
static void facet_draw(window_t*w,const gfx_target_t*t){facet_t*s=w->user_data;const ui_runtime_theme_t*h=ui_theme_current();gfx_clear(t,h->canvas);se_header(t,"FACETS - VISUAL STRATA","Facet",false);int x0=78,y0=108;for(int i=0;i<6;i++){int col=i%3,row=i/3;int x=x0+col*305,y=y0+row*290,ww=286,hh=270;se_card(t,x,y,ww,hh,ca[i],i==s->selected?h->ink:h->border);gfx_fill_rect_gradient(t,x+1,y+1,ww-2,hh-2,ca[i],cb[i]);ui_draw_bitmap_scaled(t,x+ww-95,y+hh-105,82,82,ui_logo_big());se_bold(t,x+20,y+hh-54,names[i],0xFFFFFFFF);se_text(t,x+20,y+hh-31,i==0?"48 frames - 4k":"still facet",0xFFFFFFFF);}int ix=w->width-370;se_card(t,ix,108,330,w->height-150,h->surface,h->border);se_text(t,ix+24,134,"SELECTED FACET",h->muted);se_bold(t,ix+24,170,names[s->selected],h->ink);se_text(t,ix+24,204,"colour              warm gradient",h->muted);se_text(t,ix+24,244,"depth                       10 bit",h->muted);se_text(t,ix+24,284,"strata                        warm",h->muted);se_text(t,ix+24,338,"GRADE",h->muted);for(int i=0;i<3;i++)gfx_fill_rect_gradient(t,ix+24+i*64,368,52,52,ca[(s->selected+i)%6],cb[(s->selected+i)%6]);se_text(t,ix+24,452,"WARMTH",h->muted);se_progress(t,ix+24,480,270,170,h->border,h->accent_berry);se_text(t,ix+24,526,"FACET DEPTH",h->muted);se_progress(t,ix+24,554,270,96,h->border,h->accent_berry);se_bold(t,ix+24,616,s->dark?"DARK PRISM ACTIVE":"LIGHT PEARL ACTIVE",h->ink);se_text(t,ix+24,650,"Enter applies - D toggles dark mode.",h->muted);se_text(t,78,w->height-34,s->status,h->accent_berry);}
static void facet_key(window_t*w,char c){facet_t*s=w->user_data;if(c==27){se_close(w);return;}if(c==KBD_KEY_LEFT||c==KBD_KEY_UP)s->selected=(s->selected+5)%6;else if(c==KBD_KEY_RIGHT||c==KBD_KEY_DOWN||c=='\t')s->selected=(s->selected+1)%6;else if(c=='d'||c=='D'){s->dark=!s->dark;facet_apply(s);}else if(c=='\n'||c==' ')facet_apply(s);}
static void facet_click(window_t*w,int x,int y){facet_t*s=w->user_data;if(x>=78&&x<993&&y>=108&&y<688){int col=(x-78)/305,row=(y-108)/290,i=row*3+col;if(i>=0&&i<6){s->selected=i;facet_apply(s);}}}
window_t* app_facet_open(void){facet_t*s=kmalloc(sizeof(*s));if(!s)return 0;s->selected=0;s->dark=ui_theme_current()->dark;char b[64];int64_t n=fat32_read_file(FACET_PATH,b,sizeof(b));if(n>7&&b[6]>='0'&&b[6]<='5')s->selected=b[6]-'0';se_copy(s->status,fat32_is_mounted()?"Choose a facet - Enter to apply":"Not saved - RAM only",48);window_t*w=se_workspace("Facet",facet_draw,facet_click,facet_key,s,false);if(!w)kfree(s);return w;}
